<node TEXT="MM Watch" ID="ID_700001919" CREATED="1785484000000" MODIFIED="1785484000000"><attribute NAME="name" VALUE="mmwatch"/><attribute NAME="version" VALUE="v0.2.0"/><attribute NAME="author" VALUE="Sergei Veselovskii"/><attribute NAME="freeplaneVersionFrom" VALUE="v1.12.0"/><attribute NAME="freeplaneVersionTo" VALUE=""/><attribute NAME="updateUrl" VALUE=""/><node TEXT="description" ID="ID_700000404" CREATED="1785484000000" MODIFIED="1785484000000"><node TEXT="Applies edits queued by mm.py to the open map, so Freeplane no longer has to be closed before editing a map from the command line. Arm it once per session; it stops when Freeplane exits. It never saves the map - edits arrive as unsaved changes." ID="ID_700000303" CREATED="1785484000000" MODIFIED="1785484000000"></node></node><node TEXT="changes" ID="ID_700000707" CREATED="1785484000000" MODIFIED="1785484000000"><node TEXT="v0.2.0" ID="ID_700000606" CREATED="1785484000000" MODIFIED="1785484000000"><node TEXT="initial release" ID="ID_700000505" CREATED="1785484000000" MODIFIED="1785484000000"></node></node></node><node TEXT="license" ID="ID_700000909" CREATED="1785484000000" MODIFIED="1785484000000"><node TEXT="This add-on is free software: you can redistribute it and/or modify it under the terms of the GNU General Public License as published by the Free Software Foundation, either version 2 of the License, or (at your option) any later version." ID="ID_700000808" CREATED="1785484000000" MODIFIED="1785484000000"></node></node><node TEXT="preferences.xml" ID="ID_700001010" CREATED="1785484000000" MODIFIED="1785484000000"></node><node TEXT="default.properties" ID="ID_700001111" CREATED="1785484000000" MODIFIED="1785484000000"></node><node TEXT="translations" ID="ID_700001313" CREATED="1785484000000" MODIFIED="1785484000000"><node TEXT="en" ID="ID_700001212" CREATED="1785484000000" MODIFIED="1785484000000"><attribute NAME="addons.${name}" VALUE="MM Watch"/><attribute NAME="addons.${name}.start" VALUE="Start map watcher"/></node></node><node TEXT="deinstall" ID="ID_700001414" CREATED="1785484000000" MODIFIED="1785484000000"><attribute NAME="delete" VALUE="${installationbase}/addons/${name}.script.xml"/><attribute NAME="delete" VALUE="${installationbase}/addons/${name}/scripts/mm-watch.groovy"/></node><node TEXT="scripts" ID="ID_700001515" CREATED="1785484000000" MODIFIED="1785484000000"><node TEXT="mm-watch.groovy" ID="ID_700000202" CREATED="1785484000000" MODIFIED="1785484000000"><attribute NAME="menuTitleKey" VALUE="addons.${name}.start"/><attribute NAME="menuLocation" VALUE="main_menu_scripting/addons.${name}"/><attribute NAME="executionMode" VALUE="on_single_node"/><attribute NAME="keyboardShortcut" VALUE="control alt shift W"/><attribute NAME="execute_scripts_without_asking" VALUE="true"/><attribute NAME="execute_scripts_without_exec_restriction" VALUE="false"/><attribute NAME="execute_scripts_without_file_restriction" VALUE="true"/><attribute NAME="execute_scripts_without_network_restriction" VALUE="false"/><attribute NAME="execute_scripts_without_write_restriction" VALUE="true"/><node TEXT="// mm-watch.groovy - lets Freeplane stay open while mm.py edits a map.&#xa;//&#xa;// mm.py --live appends JSON commands to ~/.mm-bridge/queue.jsonl instead of&#xa;// rewriting the .mm file. This watcher consumes that queue and applies each&#xa;// command to the *open, in-memory* map on the Swing thread, so there is never&#xa;// a second writer competing with Freeplane for the file.&#xa;//&#xa;// Armed from the menu: Tools &gt; Scripts &gt; MM Watch &gt; Start map watcher.&#xa;// Runs as a daemon thread, so it dies with Freeplane.&#xa;//&#xa;// It deliberately does NOT save the map. Edits appear as unsaved changes and&#xa;// you decide when to write them out - that keeps undo working and keeps&#xa;// Freeplane the only process that ever writes the file.&#xa;&#xa;import groovy.json.JsonSlurper&#xa;import groovy.json.JsonOutput&#xa;import javax.swing.SwingUtilities&#xa;import java.io.RandomAccessFile&#xa;import java.nio.channels.FileLock&#xa;import org.freeplane.core.util.LogUtils&#xa;&#xa;final String HOME   = System.getProperty('user.home')&#xa;// User-level, not per project: every command carries the absolute path of the&#xa;// map it targets, so one queue serves every map collection and this script&#xa;// needs no configuration. Do not make these project-relative again.&#xa;final File BRIDGE   = new File(HOME, '.mm-bridge')&#xa;final File QUEUE    = new File(BRIDGE, 'queue.jsonl')&#xa;final File STATUS   = new File(BRIDGE, 'status.json')&#xa;final long POLL_MS  = 400&#xa;final long BEAT_MS  = 3000&#xa;final String GUARD  = 'mm.watch.armed'&#xa;&#xa;if ('1' == System.getProperty(GUARD)) {&#xa;    ui.informationMessage('mm-watch is already armed in this Freeplane session.')&#xa;    return&#xa;}&#xa;&#xa;def controller = c          // proxy captured here; only ever touched on the EDT&#xa;def slurper = new JsonSlurper()&#xa;&#xa;// ---------------------------------------------------------------- helpers&#xa;&#xa;// Locate an open map by canonical path. Uses openMaps rather than the current&#xa;// map so a command lands correctly even when another tab has focus.&#xa;def findMap = { String wanted -&gt;&#xa;    for (m in controller.openMaps) {&#xa;        try {&#xa;            File f = m.file&#xa;            if (f != null &amp;&amp; f.canonicalPath == wanted) return m&#xa;        } catch (Throwable ignored) { }&#xa;    }&#xa;    return null&#xa;}&#xa;&#xa;// Create a node and, recursively, any children the command carries.&#xa;// mm.py cannot address a node it created live (targets resolve against the file on&#xa;// disk), but in here we hold the live Node objects, so nesting is free. This is what&#xa;// lets the bridge post an options node with its options underneath in one command.&#xa;def build&#xa;build = { parent, java.util.Map spec -&gt;&#xa;    def kid = parent.createChild(spec.text as String)&#xa;    (spec.icons ?: []).each { kid.icons.add(it as String) }&#xa;    if (spec.note) kid.note = spec.note as String&#xa;    if (spec.color) try { kid.style.textColorCode = spec.color as String } catch (Throwable ignored) { }&#xa;    (spec.children ?: []).each { child -&gt; build(kid, child as java.util.Map) }&#xa;    return kid&#xa;}&#xa;&#xa;// Apply one command. Must run on the EDT. Returns a human-readable result.&#xa;def apply = { java.util.Map cmd -&gt;&#xa;    if (!cmd.map) return 'ERR no map in command'&#xa;    String wanted = new File(cmd.map as String).canonicalPath&#xa;    def mp = findMap(wanted)&#xa;    if (mp == null) return &quot;SKIP map not open: ${cmd.map}&quot;&#xa;&#xa;    def target = cmd.target ? mp.node(cmd.target as String) : mp.root&#xa;    if (target == null) return &quot;ERR node not found: ${cmd.target}&quot;&#xa;&#xa;    switch (cmd.op) {&#xa;        case 'add':&#xa;            def kid = build(target, cmd)&#xa;            return &quot;OK add ${kid.id} under ${target.id}&quot;&#xa;        case 'icon':&#xa;            if (cmd.clear) target.icons.clear()&#xa;            (cmd.icons ?: []).each { target.icons.add(it as String) }&#xa;            return &quot;OK icon ${target.id}&quot;&#xa;        case 'note':&#xa;            target.note = cmd.note as String&#xa;            return &quot;OK note ${target.id}&quot;&#xa;        case 'text':&#xa;            target.text = cmd.text as String&#xa;            return &quot;OK text ${target.id}&quot;&#xa;        case 'color':&#xa;            target.style.textColorCode = cmd.color as String&#xa;            return &quot;OK color ${target.id}&quot;&#xa;        default:&#xa;            return &quot;ERR unknown op: ${cmd.op}&quot;&#xa;    }&#xa;}&#xa;&#xa;// Drain the queue atomically: read everything under an exclusive lock, then&#xa;// truncate, so a concurrent mm.py append cannot be lost.&#xa;def drain = {&#xa;    if (!QUEUE.exists() || QUEUE.length() == 0) return ''&#xa;    RandomAccessFile raf = new RandomAccessFile(QUEUE, 'rw')&#xa;    FileLock lock = null&#xa;    try {&#xa;        lock = raf.channel.lock()&#xa;        int len = (int) raf.length()&#xa;        if (len == 0) return ''&#xa;        byte[] buf = new byte[len]&#xa;        raf.readFully(buf)&#xa;        raf.setLength(0)&#xa;        return new String(buf, 'UTF-8')&#xa;    } finally {&#xa;        if (lock != null) try { lock.release() } catch (Throwable ignored) { }&#xa;        raf.close()&#xa;    }&#xa;}&#xa;&#xa;// No pid here: ProcessHandle.current().pid() needs RuntimePermission&#xa;// &quot;manageProcess&quot;, which the add-on does not request (and should not). The&#xa;// heartbeat timestamp is the liveness signal, so the pid bought nothing.&#xa;boolean[] statusBroken = [false]&#xa;def writeStatus = { boolean armed, String last, int applied, int failed -&gt;&#xa;    try {&#xa;        BRIDGE.mkdirs()&#xa;        STATUS.setText(JsonOutput.toJson([&#xa;                armed  : armed,&#xa;                ts     : System.currentTimeMillis(),&#xa;                applied: applied,&#xa;                failed : failed,&#xa;                last   : last ?: '',&#xa;        ]), 'UTF-8')&#xa;    } catch (Throwable t) {&#xa;        // warn once, not every heartbeat - this used to spam the log&#xa;        if (!statusBroken[0]) {&#xa;            statusBroken[0] = true&#xa;            LogUtils.warn('mm-watch: cannot write status (will not repeat): ' + t)&#xa;        }&#xa;    }&#xa;}&#xa;&#xa;// ---------------------------------------------------------------- worker&#xa;&#xa;int[] tally = [0, 0]        // applied, failed&#xa;Thread worker = new Thread({&#xa;    String last = 'armed'&#xa;    long lastBeat = 0&#xa;    writeStatus(true, last, 0, 0)&#xa;    LogUtils.info('mm-watch: armed, watching ' + QUEUE)&#xa;    while (!Thread.currentThread().isInterrupted()) {&#xa;        try {&#xa;            String payload = drain()&#xa;            if (payload) {&#xa;                for (String line : payload.readLines()) {&#xa;                    line = line.trim()&#xa;                    if (!line || line.startsWith('#')) continue&#xa;                    def cmd&#xa;                    try {&#xa;                        cmd = slurper.parseText(line)&#xa;                    } catch (Throwable pe) {&#xa;                        tally[1]++; last = 'ERR bad json: ' + pe.message&#xa;                        LogUtils.warn('mm-watch: ' + last); continue&#xa;                    }&#xa;                    String[] out = new String[1]&#xa;                    SwingUtilities.invokeAndWait({&#xa;                        try { out[0] = apply(cmd) }&#xa;                        catch (Throwable ae) { out[0] = 'ERR ' + ae }&#xa;                    })&#xa;                    last = out[0]&#xa;                    if (last?.startsWith('OK')) tally[0]++ else tally[1]++&#xa;                    LogUtils.info('mm-watch: ' + last)&#xa;                }&#xa;                writeStatus(true, last, tally[0], tally[1])&#xa;                lastBeat = System.currentTimeMillis()&#xa;            } else if (System.currentTimeMillis() - lastBeat &gt; BEAT_MS) {&#xa;                writeStatus(true, last, tally[0], tally[1])&#xa;                lastBeat = System.currentTimeMillis()&#xa;            }&#xa;        } catch (InterruptedException ie) {&#xa;            break&#xa;        } catch (Throwable t) {&#xa;            LogUtils.warn('mm-watch: loop error: ' + t)&#xa;        }&#xa;        try { Thread.sleep(POLL_MS) } catch (InterruptedException ie) { break }&#xa;    }&#xa;    writeStatus(false, 'stopped', tally[0], tally[1])&#xa;    LogUtils.info('mm-watch: stopped')&#xa;}, 'mm-watch')&#xa;worker.daemon = true&#xa;worker.start()&#xa;&#xa;System.setProperty(GUARD, '1')&#xa;ui.informationMessage(&quot;mm-watch armed.\n\nQueue: ${QUEUE}\nStatus: ${STATUS}\n\n&quot; +&#xa;        'Edits arrive as unsaved changes - save when you are ready.\n' +&#xa;        'Stops automatically when Freeplane exits.')&#xa;" ID="ID_700000101" CREATED="1785484000000" MODIFIED="1785484000000"></node></node></node><node TEXT="lib" ID="ID_700001616" CREATED="1785484000000" MODIFIED="1785484000000"></node><node TEXT="zips" ID="ID_700001717" CREATED="1785484000000" MODIFIED="1785484000000"></node><node TEXT="images" ID="ID_700001818" CREATED="1785484000000" MODIFIED="1785484000000"></node></node>
